import sqlite3
import json
from itertools import combinations, permutations

# ============================================================
# LOAD MAP DATA
# ============================================================
conn = sqlite3.connect('/data/maps/e2e_test_case_0.Civ6Map')
cur = conn.cursor()
cur.execute("SELECT Width, Height FROM Map")
WIDTH, HEIGHT = cur.fetchone()

plots = {}
cur.execute("SELECT ID, TerrainType, IsImpassable FROM Plots")
for pid, terrain, impass in cur.fetchall():
    x, y = pid % WIDTH, pid // WIDTH
    plots[(x, y)] = {
        'terrain': terrain,
        'impassable': bool(impass),
        'feature': None
    }

cur.execute("SELECT ID, FeatureType FROM PlotFeatures")
for pid, feature in cur.fetchall():
    x, y = pid % WIDTH, pid // WIDTH
    if (x, y) in plots:
        plots[(x, y)]['feature'] = feature

river_data = {}
cur.execute("SELECT ID, IsNEOfRiver, IsWOfRiver, IsNWOfRiver FROM PlotRivers")
for pid, ne, w, nw in cur.fetchall():
    x, y = pid % WIDTH, pid // WIDTH
    river_data[(x, y)] = {'NE': bool(ne), 'W': bool(w), 'NW': bool(nw)}
conn.close()

# ============================================================
# HEX FUNCTIONS
# ============================================================
def get_neighbors(x, y):
    if y % 2 == 0:
        return [(x+1,y),(x-1,y),(x,y+1),(x-1,y+1),(x,y-1),(x-1,y-1)]
    else:
        return [(x+1,y),(x-1,y),(x+1,y+1),(x,y+1),(x+1,y-1),(x,y-1)]

def offset_to_cube(x, y):
    cx = x - (y - (y & 1)) // 2
    cz = y
    cy = -cx - cz
    return cx, cy, cz

def hex_distance(x1, y1, x2, y2):
    ax, ay, az = offset_to_cube(x1, y1)
    bx, by, bz = offset_to_cube(x2, y2)
    return max(abs(ax - bx), abs(ay - by), abs(az - bz))

def tile_has_river(x, y):
    if (x, y) in river_data:
        r = river_data[(x, y)]
        if r['NE'] or r['W'] or r['NW']:
            return True
    # Check neighbor edges
    if y % 2 == 0:
        e_neighbor = (x+1, y)
        sw_neighbor = (x-1, y-1)
        se_neighbor = (x, y-1)
    else:
        e_neighbor = (x+1, y)
        sw_neighbor = (x, y-1)
        se_neighbor = (x+1, y-1)

    if e_neighbor in river_data and river_data[e_neighbor]['W']:
        return True
    if sw_neighbor in river_data and river_data[sw_neighbor]['NE']:
        return True
    if se_neighbor in river_data and river_data[se_neighbor]['NW']:
        return True
    return False

# ============================================================
# TILE CLASSIFICATION
# ============================================================
def is_mountain(x, y):
    return (x, y) in plots and 'MOUNTAIN' in plots[(x,y)]['terrain']

def is_land(x, y):
    if (x, y) not in plots:
        return False
    t = plots[(x,y)]['terrain']
    return t not in ('TERRAIN_OCEAN', 'TERRAIN_COAST') and not plots[(x,y)]['impassable']

def is_coast(x, y):
    return (x, y) in plots and plots[(x,y)]['terrain'] == 'TERRAIN_COAST' and not plots[(x,y)]['impassable']

def has_feature(x, y, feature):
    return (x, y) in plots and plots[(x,y)]['feature'] == feature

# Buildable land tiles (for city center and regular districts)
buildable_land = set()
for (x, y), p in plots.items():
    if p['terrain'] not in ('TERRAIN_OCEAN', 'TERRAIN_COAST') and not p['impassable']:
        buildable_land.add((x, y))

# Buildable coast tiles adjacent to land (for harbor)
harbor_candidates = set()
for (x, y), p in plots.items():
    if p['terrain'] == 'TERRAIN_COAST' and not p['impassable']:
        # Must be adjacent to land
        if any(is_land(nx, ny) or is_mountain(nx, ny) for nx, ny in get_neighbors(x, y)):
            harbor_candidates.add((x, y))

print(f"Buildable land: {len(buildable_land)}")
print(f"Harbor candidates: {len(harbor_candidates)}")

# ============================================================
# ADJACENCY BONUS CALCULATION
# ============================================================
def calc_adjacency(district_type, dx, dy, placements, city_center):
    """Calculate adjacency bonus for a district at (dx, dy).
    placements: dict of {district_type: (x,y)}
    city_center: (x, y)
    """
    neighbors = get_neighbors(dx, dy)

    # Classify each neighbor
    adj_mountains = 0
    adj_districts = 0  # includes city center
    adj_geothermal = 0
    adj_reef = 0
    adj_rainforest = 0
    adj_woods = 0

    # Build set of all placed positions (districts + city center)
    placed_positions = {city_center: 'CITY_CENTER'}
    for dt, pos in placements.items():
        placed_positions[pos] = dt

    for nx, ny in neighbors:
        if (nx, ny) not in plots:
            continue

        # Check if it's a district/city center
        if (nx, ny) in placed_positions:
            adj_districts += 1
            # Geothermal/forest/jungle on a tile with a district are REMOVED
            continue

        # Check terrain features (only count if not occupied by a district)
        if is_mountain(nx, ny):
            adj_mountains += 1

        if has_feature(nx, ny, 'FEATURE_GEOTHERMAL_FISSURE'):
            adj_geothermal += 1

        if has_feature(nx, ny, 'FEATURE_REEF'):
            adj_reef += 1

        if has_feature(nx, ny, 'FEATURE_JUNGLE'):
            adj_rainforest += 1

        if has_feature(nx, ny, 'FEATURE_FOREST'):
            adj_woods += 1

    bonus = 0

    if district_type == 'CAMPUS':
        # +1 per mountain, +2 per geothermal, +1 per 2 rainforest/district, +1 per 2 reef
        bonus = adj_mountains + adj_geothermal * 2 + (adj_rainforest + adj_districts) // 2 + adj_reef // 2

    elif district_type == 'COMMERCIAL_HUB':
        # +2 if on river, +2 per adjacent harbor, +1 per 2 adjacent districts
        has_river = tile_has_river(dx, dy)
        adj_harbors = sum(1 for nx, ny in neighbors if (nx, ny) in placed_positions and placed_positions[(nx, ny)] == 'HARBOR')
        bonus = (2 if has_river else 0) + adj_harbors * 2 + adj_districts // 2

    elif district_type == 'HARBOR':
        # +2 if adjacent to city center, +1 per 2 adjacent districts
        adj_city = any((nx, ny) == city_center for nx, ny in neighbors)
        bonus = (2 if adj_city else 0) + adj_districts // 2
        # Sea resources would add +1 each but there are none on this map

    elif district_type == 'HOLY_SITE':
        # +1 per mountain, +1 per 2 (woods + districts)
        bonus = adj_mountains + (adj_woods + adj_districts) // 2

    elif district_type == 'INDUSTRIAL_ZONE':
        # +1 per mine, +1 per quarry, +1 per 2 districts
        # No mines/quarries on this map (no improvements placed)
        bonus = adj_districts // 2

    elif district_type == 'THEATER_SQUARE':
        # +2 per wonder (none on map), +1 per 2 districts
        bonus = adj_districts // 2

    elif district_type == 'ENTERTAINMENT_COMPLEX':
        bonus = 0

    elif district_type == 'ENCAMPMENT':
        bonus = 0

    return bonus

# ============================================================
# OPTIMIZATION
# ============================================================
# Population 9 -> floor(9/3) + 1 = 4 specialty districts
NUM_DISTRICTS = 4

# Candidate district types that can earn adjacency bonuses on this map:
# - CAMPUS: mountains + geothermal + jungle/districts
# - COMMERCIAL_HUB: rivers + districts
# - HARBOR: city center + districts (must be on coast)
# - HOLY_SITE: mountains + forests/districts
# - INDUSTRIAL_ZONE: districts only (no mines)
# - THEATER_SQUARE: districts only (no wonders)
# - ENTERTAINMENT_COMPLEX: 0 bonus
# - ENCAMPMENT: 0 bonus (can't be adj to CC)

# Best candidates: CAMPUS (geothermal + mountain), COMMERCIAL_HUB (river), HARBOR (CC adj), HOLY_SITE (mountain)
# Then INDUSTRIAL_ZONE and THEATER_SQUARE as cluster bonuses

# Let's enumerate district type combos
DISTRICT_TYPES = ['CAMPUS', 'COMMERCIAL_HUB', 'HARBOR', 'HOLY_SITE', 'INDUSTRIAL_ZONE', 'THEATER_SQUARE']

best_total = -1
best_solution = None

# For each city center position
for cc in buildable_land:
    cx, cy = cc

    # Valid district positions: within 3 tiles of city center
    valid_land = [pos for pos in buildable_land if pos != cc and hex_distance(cx, cy, pos[0], pos[1]) <= 3]
    valid_harbor = [pos for pos in harbor_candidates if hex_distance(cx, cy, pos[0], pos[1]) <= 3]

    if len(valid_land) < NUM_DISTRICTS - 1:  # Need at least 3 land spots (may need harbor on coast)
        continue

    # Try each combination of 4 district types
    for district_combo in combinations(DISTRICT_TYPES, NUM_DISTRICTS):
        has_harbor = 'HARBOR' in district_combo
        has_encampment = 'ENCAMPMENT' in district_combo

        land_districts = [d for d in district_combo if d != 'HARBOR']
        harbor_districts = [d for d in district_combo if d == 'HARBOR']

        # Need len(land_districts) land positions and len(harbor_districts) coast positions
        if len(valid_land) < len(land_districts):
            continue
        if has_harbor and len(valid_harbor) == 0:
            continue

        # For harbor + land combination
        if has_harbor:
            for harbor_pos in valid_harbor:
                # Remaining land districts
                for land_perm in permutations(valid_land, len(land_districts)):
                    # Check no overlaps
                    all_pos = list(land_perm) + [harbor_pos]
                    if len(set(all_pos)) != len(all_pos):
                        continue

                    # Build placement dict
                    placements = {}
                    for i, d in enumerate(land_districts):
                        placements[d] = land_perm[i]
                    placements['HARBOR'] = harbor_pos

                    # Check encampment not adjacent to CC
                    if has_encampment and 'ENCAMPMENT' in placements:
                        ex, ey = placements['ENCAMPMENT']
                        if cc in get_neighbors(ex, ey):
                            continue

                    # Calculate total adjacency
                    total = 0
                    bonuses = {}
                    for d, pos in placements.items():
                        b = calc_adjacency(d, pos[0], pos[1], placements, cc)
                        bonuses[d] = b
                        total += b

                    if total > best_total:
                        best_total = total
                        best_solution = {
                            'city_center': list(cc),
                            'placements': {d: list(p) for d, p in placements.items()},
                            'adjacency_bonuses': bonuses,
                            'total_adjacency': total
                        }
                        print(f"New best: total={total}, cc={cc}, placements={placements}, bonuses={bonuses}")
        else:
            # All land districts
            for land_perm in permutations(valid_land, len(land_districts)):
                placements = {}
                for i, d in enumerate(land_districts):
                    placements[d] = land_perm[i]

                if has_encampment and 'ENCAMPMENT' in placements:
                    ex, ey = placements['ENCAMPMENT']
                    if cc in get_neighbors(ex, ey):
                        continue

                total = 0
                bonuses = {}
                for d, pos in placements.items():
                    b = calc_adjacency(d, pos[0], pos[1], placements, cc)
                    bonuses[d] = b
                    total += b

                if total > best_total:
                    best_total = total
                    best_solution = {
                        'city_center': list(cc),
                        'placements': {d: list(p) for d, p in placements.items()},
                        'adjacency_bonuses': bonuses,
                        'total_adjacency': total
                    }
                    print(f"New best: total={total}, cc={cc}, placements={placements}, bonuses={bonuses}")

print(f"\n\nFINAL BEST: total={best_total}")
print(json.dumps(best_solution, indent=2))

